<template>
  <main class="manufacturing-page" :aria-busy="busy">
    <header><div><h1>制造映射与产出</h1><p>逐位置说明工程结构、制造投入和生成工序之间的关系。</p></div><button :disabled="busy" @click="reload">刷新</button></header>
