    <section><header><h2>制造关系目录</h2><button v-if="permissions.has('plm-engineering-manufacturing:add')" :disabled="locked || !scope" @click="create">新建制造关系</button></header>
      <form class="inline" @submit.prevent="loadPage(1)"><label>名称<input v-model="search" aria-label="制造关系搜索" :disabled="busy" maxlength="256" /></label><button :disabled="busy || !canRead">搜索</button></form>
      <ul><li v-for="r in rows" :key="r.reference.id">{{ r.body.name }} · v{{ r.reference.version }} · {{ r.body.outputs.length }} 个产出位置 <button :disabled="busy" @click="open(r.reference.id)">打开制造关系</button></li></ul><p v-if="!rows.length">当前范围内没有制造关系。</p>
      <nav><button :disabled="busy || page === 1" @click="loadPage(page - 1)">上一页</button><span>第 {{ page }} 页</span><button :disabled="busy || rows.length < 20" @click="loadPage(page + 1)">下一页</button></nav>
    </section>
    <section v-if="editing"><h2>准确来源</h2><p>映射和产出定义是技术草稿，仍需规格原证、专业评审及工程冻结。</p>
      <form class="inline" @submit.prevent="findParents(1)"><label>工程修订编号<input v-model="parentSearch" aria-label="工程修订搜索" :disabled="locked" /></label><button :disabled="locked">查找工程修订</button><button type="button" :disabled="locked || !moreParents" @click="findParents(parentPage + 1)">更多工程修订</button></form>
      <label>工程修订<select v-model="parentChoice" aria-label="工程修订选择" :disabled="locked || !canWrite"><option value="">请选择当前版本</option><option v-for="p in parents" :key="key(p.reference)" :value="key(p.reference)">{{ p.revisionCode }} · v{{ p.reference.version }} · {{ p.draft.goal }}</option></select></label>
      <button :disabled="locked || !parentChoice || !canWrite" @click="findSources(1)">查找本修订结构与工艺</button><button :disabled="locked || !moreSources" @click="findSources(sourcePage + 1)">更多结构与工艺</button>
      <div class="grid"><label>工程结构<select v-model="ebomChoice" aria-label="工程结构选择" :disabled="locked || !canWrite"><option value="">请选择 EBOM</option><option v-for="b in choices.filter(x => x.body.kind === 'EBOM')" :key="key(b.reference)" :value="key(b.reference)">{{ b.body.name }} · v{{ b.reference.version }}</option></select></label>
        <label>制造结构<select v-model="mbomChoice" aria-label="制造结构选择" :disabled="locked || !canWrite"><option value="">请选择 MBOM</option><option v-for="b in choices.filter(x => x.body.kind === 'MBOM')" :key="key(b.reference)" :value="key(b.reference)">{{ b.body.name }} · v{{ b.reference.version }}</option></select></label>
        <label>工艺<select v-model="routeChoice" aria-label="制造工艺选择" :disabled="locked || !canWrite"><option value="">请选择工艺</option><option v-for="r in routes" :key="key(r.reference)" :value="key(r.reference)">{{ r.body.name }} · v{{ r.reference.version }}</option></select></label></div>
      <button :disabled="locked || !canWrite || !ebomChoice || !mbomChoice || !routeChoice" @click="adoptSources">采用所选来源</button>
