      <article v-for="(o, i) in body.outputs" :key="o.outputOccurrenceId"><header><h3>产出 {{ i + 1 }} · {{ o.name }}</h3><button type="button" @click="body.outputs.splice(i, 1)">移除产出</button></header><div class="grid">
        <label>名称<input v-model="o.name" :aria-label="`产出名称 ${i + 1}`" maxlength="256" required /></label><label>技术角色<select v-model="o.role" :aria-label="`产出角色 ${i + 1}`"><option value="PRIMARY">主产物</option><option value="CO_PRODUCT">联产物</option><option value="BY_PRODUCT">副产物</option><option value="INTERMEDIATE">中间物</option></select></label>
