        <label>前序中间产出（可多选）<select v-model="o.fromOutputOccurrenceIds" multiple :aria-label="`前序产出 ${i + 1}`"><option v-for="x in body.outputs.filter(x => x.outputOccurrenceId !== o.outputOccurrenceId)" :key="x.outputOccurrenceId" :value="x.outputOccurrenceId">{{ x.name }} · {{ x.role }}</option><option v-for="v in absent(o.fromOutputOccurrenceIds, body.outputs.map(x => x.outputOccurrenceId))" :key="v" :value="v">原产出待核对 · {{ v }}</option></select></label>
        <label>数量类型<select v-model="o.quantityKind" :aria-label="`数量类型 ${i + 1}`"><option value="UNKNOWN">待定义</option><option value="FIXED_RATIO">固定配比</option><option value="TARGET">目标</option><option value="RANGE">范围</option><option value="OBSERVATION">观测要求</option></select></label>
        <label>数量<input :value="o.quantity ?? ''" :aria-label="`产出数量 ${i + 1}`" maxlength="2050" inputmode="decimal" @input="o.quantity = ($event.target as HTMLInputElement).value || null" /></label>
        <label>下限<input :value="o.minimum ?? ''" maxlength="2050" @input="o.minimum = ($event.target as HTMLInputElement).value || null" /></label><label>上限<input :value="o.maximum ?? ''" maxlength="2050" @input="o.maximum = ($event.target as HTMLInputElement).value || null" /></label>
