        <label>分母<input :value="o.denominator ?? ''" :aria-label="`数量分母 ${i + 1}`" maxlength="2050" @input="o.denominator = ($event.target as HTMLInputElement).value || null" /></label>
        <label>分母单位<select :value="o.denominatorUnitRef ? key(o.denominatorUnitRef) : ''" :aria-label="`分母单位 ${i + 1}`" @change="chooseUnit(o, 'denominatorUnitRef', ($event.target as HTMLSelectElement).value)"><option value="">待确认</option><option v-if="o.denominatorUnitRef && !units.some(u => key(u.reference) === key(o.denominatorUnitRef!))" :value="key(o.denominatorUnitRef)">已保存单位 · v{{ o.denominatorUnitRef.version }}</option><option v-for="u in units" :key="key(u.reference)" :value="key(u.reference)">{{ u.profile.code }} · {{ u.profile.dimensionKey }}</option></select></label>
        <label>数量基准与界限<textarea v-model="o.quantityBasis" maxlength="4000" /></label><label>规格与证明待办<textarea v-model="o.specRequirement" :aria-label="`产出规格 ${i + 1}`" maxlength="4000" /></label><label>关系技术依据<textarea v-model="o.relationEvidence" maxlength="4000" /></label><label>无投入生成依据<textarea v-model="o.noInputBasis" maxlength="4000" /></label><label>处置责任说明<textarea v-model="o.dispositionRequirement" maxlength="4000" /></label>
      </div><p>{{ same(o.configurationRef, body.configurationRef) && o.configurationRef ? '采用本关系配置。' : '产出配置待核对。' }}</p><button type="button" :disabled="!body.configurationRef" @click="o.configurationRef = copy(body.configurationRef)">采用本关系配置</button></article>
      <button type="button" @click="addOutput">添加产出</button><button>保存制造关系版本</button>
    </fieldset></form></section>
    <section v-if="editing"><h2>产物与单位来源</h2><form class="inline" @submit.prevent="findProducts(1)"><label>工程产品编码<input v-model="productSearch" aria-label="工程产品搜索" :disabled="locked" /></label><button :disabled="locked">查找工程产品</button><button type="button" :disabled="locked || !moreProducts" @click="findProducts(productPage + 1)">更多工程产品</button></form>
      <form class="inline" @submit.prevent="findUnits(1)"><label>单位编码<input v-model="unitSearch" aria-label="单位搜索" :disabled="locked" /></label><button :disabled="locked">查找单位</button><button type="button" :disabled="locked || !moreUnits" @click="findUnits(unitPage + 1)">更多单位</button></form></section>
    <section v-if="current"><h2>历史与差异</h2><form class="inline" @submit.prevent="readHistory"><label>历史版本<input v-model="historyVersion" aria-label="制造历史版本" pattern="[1-9][0-9]*" required /></label><button :disabled="busy">读取历史</button></form><details v-if="history"><summary>{{ history.body.name }} · v{{ history.reference.version }} 原件</summary><pre>{{ history.originalJson }}</pre></details>
      <form class="inline" @submit.prevent="readDiff"><label>起始版本<input v-model="beforeVersion" aria-label="制造差异起始版本" pattern="[1-9][0-9]*" required /></label><label>结束版本<input v-model="afterVersion" aria-label="制造差异结束版本" pattern="[1-9][0-9]*" required /></label><button :disabled="busy">比较版本</button></form><details v-for="c in diff?.changes" :key="c.path"><summary>{{ c.path }}</summary><div class="grid"><pre>{{ c.before }}</pre><pre>{{ c.after }}</pre></div></details>
    </section>
  </main>
</template>
<script setup lang="ts">
import { computed, onMounted, onBeforeUnmount, ref, watch } from 'vue'
import { manufacturingApi, type ManufacturingSnapshot, type ManufacturingBody, type ManufacturingOutput, type ManufacturingCommand } from '@/api/plm/engineeringManufacturing'
import { bomApi, type BomSnapshot } from '@/api/plm/engineeringBom'
import { routingApi, type RoutingSnapshot } from '@/api/plm/engineeringRouting'
import { revisionApi, type RevisionSnapshot, type RevisionDiff } from '@/api/plm/engineeringRevisions'
import { engineeringApi, type EngineeringReference, type EngineeringVersion, type EngineeringScope } from '@/api/plm/engineeringProducts'
import { uomApi, type UomVersion } from '@/api/erp/uomProfiles'
import { pendingManufacturing, manufacturingResponse as result, saveManufacturing, resolveManufacturing, type PendingManufacturing } from '@/auth/engineeringManufacturingRecovery'
import { AUTH_EVENT, identityStamp, requireIdentity } from '@/auth/identity'
import { authenticationCanRead } from '@/auth/browserAuthentication'
import { usePermissionStore } from '@/stores/permission'
const permissions = usePermissionStore(), canRead = computed(() => permissions.loaded && permissions.has('plm-engineering-manufacturing:query'))
const canWrite = computed(() => canRead.value && permissions.has(`plm-engineering-manufacturing:${current.value ? 'edit' : 'add'}`))
const busy = ref(false), error = ref(''), notice = ref(''), scope = ref<EngineeringScope | null>(null), pending = ref<PendingManufacturing | null>(null), locked = computed(() => busy.value || !!pending.value)
const rows = ref<ManufacturingSnapshot[]>([]), current = ref<ManufacturingSnapshot | null>(null), body = ref<ManufacturingBody | null>(null), editing = ref(false), id = ref(''), reason = ref(''), search = ref(''), page = ref(1)
const parents = ref<RevisionSnapshot[]>([]), parentSearch = ref(''), parentChoice = ref(''), parentPage = ref(1), moreParents = ref(false)
const choices = ref<BomSnapshot[]>([]), routes = ref<RoutingSnapshot[]>([]), sourcePage = ref(1), moreSources = ref(false), ebomChoice = ref(''), mbomChoice = ref(''), routeChoice = ref('')
const ebom = ref<BomSnapshot | null>(null), mbom = ref<BomSnapshot | null>(null), routing = ref<RoutingSnapshot | null>(null)
const products = ref<EngineeringVersion[]>([]), productSearch = ref(''), productPage = ref(1), moreProducts = ref(false), units = ref<UomVersion[]>([]), unitSearch = ref(''), unitPage = ref(1), moreUnits = ref(false)
const history = ref<ManufacturingSnapshot | null>(null), historyVersion = ref('1'), beforeVersion = ref('1'), afterVersion = ref('1'), diff = ref<RevisionDiff | null>(null)
const copy = <T,>(v: T): T => JSON.parse(JSON.stringify(v)) as T
const key = (r: EngineeringReference) => `${r.owner}:${r.id}:${r.version}:${r.digest}`
const same = (a: EngineeringReference | null, b: EngineeringReference | null) => a && b ? key(a) === key(b) : a === b
const absent = (values: string[], known: string[] = []) => values.filter(v => !known.includes(v))
let generation = 0, live = true
function finding(text: string): string { const [code = text, ...positions] = text.split(':'); if (['EBOM', 'MBOM', 'ROUTING'].includes(code)) return ({ EBOM: '工程结构', MBOM: '制造结构', ROUTING: '工艺' }[code] ?? '') + '：' + finding(positions.join(':')); const labels: Record<string, string> = { UNMAPPED_EBOM_OCCURRENCE: '工程位置尚未映射', UNMAPPED_MBOM_OCCURRENCE: '制造投入尚未说明来源', UNUSED_MANUFACTURING_INPUT: '制造投入尚未说明产出关系', PRIMARY_PRODUCT_OUTPUT_REQUIRED: '根产品缺少准确主产出', CONFIGURATION_REQUIRED: '工程配置待补齐', OUTPUT_CONFIGURATION_MISMATCH: '产出配置与本关系不一致', SITE_REQUIRED: '制造场所待确认', MANUFACTURING_SITE_MISMATCH: '制造结构与工艺场所不一致', MBOM_ROUTING_MISMATCH: '制造结构所用工艺与本关系不一致', OUTPUT_FLOW_CYCLE: '中间物流向存在循环', INTERMEDIATE_FLOW_ORDER_UNPROVEN: '中间物流向没有前后工序依据', NO_INPUT_BASIS_REQUIRED: '无投入生成尚缺工程依据', DENOMINATOR_REQUIRED: '配比的分母及单位待补齐', QUANTITY_RANGE_REVERSED: '数量下限高于上限', QUANTITY_BOUNDARY_INVALID: '数量或分母界限不符', FORMAL_RELATION_SET_PROOFS_REQUIRED: '正式输出关系仍需规格原证和专业依据', OUTPUT_SPECIFICATION_PROOF_REQUIRED: '产物自身规格原证待补齐', OUTPUT_RELATION_PROOF_REQUIRED: '产出关系专业依据待确认', MAPPING_PROFESSIONAL_EVIDENCE_REQUIRED: '映射差异仍待专业评审', QUANTITY_APPLICATION_REVIEW_REQUIRED: '数量适用依据待评审' }; const label = labels[code] ?? (code.endsWith('SOURCE_CHANGED') ? '引用来源已变化，需重新核对' : '位置、来源或数量依据仍待补齐');
  const context = positions.map(id => {
    const e = ebom.value?.body.occurrences.find(x => x.occurrenceId === id), m = mbom.value?.body.occurrences.find(x => x.occurrenceId === id)
    const o = body.value?.outputs.find(x => x.outputOccurrenceId === id), op = routing.value?.body.operations.find(x => x.occurrenceId === id)
    const map = body.value?.mappings.findIndex(x => x.mapId === id) ?? -1
    return e ? `${e.path} / ${e.name}` : m ? `${m.path} / ${m.name}` : o ? o.name : op ? op.name : map >= 0 ? `对应 ${map + 1}` : id
  }).filter(Boolean).join(' → ')
  return context ? `${label}：${context}` : label }
function clearEditor() { current.value = null; body.value = null; editing.value = false; id.value = ''; reason.value = ''; parents.value = []; parentSearch.value = parentChoice.value = ''; choices.value = []; routes.value = []; ebomChoice.value = mbomChoice.value = routeChoice.value = ''; ebom.value = mbom.value = null; routing.value = null; products.value = []; units.value = []; productSearch.value = unitSearch.value = ''; history.value = null; diff.value = null; moreParents.value = moreSources.value = moreProducts.value = moreUnits.value = false }
function clearPrivate() { clearEditor(); rows.value = []; search.value = ''; page.value = 1 }
function syncPending() { pending.value = scope.value ? pendingManufacturing(scope.value) : null }
async function run(action: (check: () => void) => Promise<void>) { if (busy.value) return; const stamp = identityStamp(), epoch = generation; const check = () => { requireIdentity(stamp); if (!live || epoch !== generation || !authenticationCanRead()) throw new Error('当前身份已变化。') }; busy.value = true; error.value = notice.value = ''; try { check(); await action(check); check() } catch (e: any) { try { check(); const status = e?.response?.status; if ([401, 403].includes(status)) clearPrivate(); error.value = [401, 403].includes(status) ? '当前无权读取制造关系或其来源。' : status === 412 ? '关系或来源版本已变化，请恢复原操作后重新核对。' : /^[A-Z][A-Z0-9_]+$/.test(e?.response?.data?.message ?? '') ? '请核对输入、来源和原操作状态。' : e?.message || '结果尚未确认。' } catch { /* Obsolete identity. */ } } finally { try { check(); syncPending(); busy.value = false } catch { if (live && epoch === generation) busy.value = false } } }
function setCurrent(value: ManufacturingSnapshot) { clearEditor(); current.value = value; body.value = copy(value.body); editing.value = true; id.value = value.reference.id; afterVersion.value = value.reference.version }
async function reload() { await run(async check => { clearPrivate(); scope.value = null; if (!permissions.loaded) await permissions.loadMyActions(); check(); if (!canRead.value) throw new Error('当前没有读取制造关系的权限。'); const s = result(await manufacturingApi.scope()); check(); scope.value = s; const values = result(await manufacturingApi.list()); check(); rows.value = values }) }
async function loadPage(target: number) { await run(async check => { rows.value = []; const values = result(await manufacturingApi.list(undefined, search.value, target)); check(); rows.value = values; page.value = target }) }
async function loadOriginalSources(b: ManufacturingBody, check: () => void) { const e = result(await bomApi.read(b.ebomRef.id, b.ebomRef.version)); check(); const m = result(await bomApi.read(b.mbomRef.id, b.mbomRef.version)); check(); const r = result(await routingApi.read(b.routingRef.id, b.routingRef.version)); check(); if (!same(e.reference, b.ebomRef) || !same(m.reference, b.mbomRef) || !same(r.reference, b.routingRef)) throw new Error('来源与所保存的版本不一致。'); ebom.value = e; mbom.value = m; routing.value = r }
async function open(value: string) { await run(async check => { clearEditor(); const saved = result(await manufacturingApi.read(value)); check(); if (saved.tenantId !== scope.value?.tenantId) throw new Error('租户已变化。'); setCurrent(saved); await loadOriginalSources(saved.body, check) }) }
function create() { if (locked.value) return; clearEditor(); editing.value = true; id.value = crypto.randomUUID() }
async function findParents(target: number) { await run(async check => { if (target === 1) { parents.value = []; parentChoice.value = '' } const values = result(await revisionApi.list(parentSearch.value, target)); check(); parents.value.push(...values.filter(p => p.isCurrent && p.draft.productRef && (!current.value || p.reference.id === current.value.body.revisionOrigin.id))); parentPage.value = target; moreParents.value = values.length === 20 }) }
async function findSources(target: number) { const parent = parents.value.find(p => key(p.reference) === parentChoice.value); if (!parent?.draft.productRef) return; await run(async check => { if (target === 1) { choices.value = []; routes.value = []; ebomChoice.value = mbomChoice.value = routeChoice.value = '' } const b = result(await bomApi.list(parent.reference.id, '', target)); check(); const r = result(await routingApi.list(parent.reference.id, '', target)); check(); choices.value.push(...b.filter(x => x.isCurrent && same(x.body.productRef, parent.draft.productRef))); routes.value.push(...r.filter(x => x.isCurrent && same(x.body.productRef, parent.draft.productRef))); sourcePage.value = target; moreSources.value = b.length === 20 || r.length === 20 }) }
function adoptSources() { if (locked.value || !canWrite.value) return; const p = parents.value.find(p => key(p.reference) === parentChoice.value), e = choices.value.find(b => key(b.reference) === ebomChoice.value && b.body.kind === 'EBOM'), m = choices.value.find(b => key(b.reference) === mbomChoice.value && b.body.kind === 'MBOM'), r = routes.value.find(x => key(x.reference) === routeChoice.value); if (!p?.draft.productRef || !e || !m || !r || [e.body.revisionOrigin.id, m.body.revisionOrigin.id, r.body.revisionOrigin.id].some(id => id !== p.reference.id)) return; const previous = body.value; body.value = { name: previous?.name ?? '', revisionOrigin: copy(p.reference), productRef: copy(p.draft.productRef), configurationRef: copy(p.draft.configuration?.reference ?? null), ebomRef: copy(e.reference), mbomRef: copy(m.reference), routingRef: copy(r.reference), siteRef: copy(m.body.siteRef), mappings: previous?.mappings ?? [], outputs: previous?.outputs ?? [] }; ebom.value = copy(e); mbom.value = copy(m); routing.value = copy(r); notice.value = '来源已选择；原有位置关系保持，请核对受影响的映射和产出配置。' }
function addMapping() { body.value?.mappings.push({ mapId: crypto.randomUUID(), kind: 'MAP', ebomOccurrenceIds: [], mbomOccurrenceIds: [], operationOccurrenceIds: [], reason: '', quantityBasis: '' }) }
function addOutput() { if (!body.value) return; body.value.outputs.push({ outputOccurrenceId: crypto.randomUUID(), role: 'PRIMARY', name: '', productRef: null, generatingOperationOccurrenceId: null, inputOccurrenceIds: [], fromOutputOccurrenceIds: [], configurationRef: copy(body.value.configurationRef), quantityKind: 'UNKNOWN', quantity: null, minimum: null, maximum: null, unitRef: null, denominator: null, denominatorUnitRef: null, quantityBasis: '', specRequirement: '', relationEvidence: '', noInputBasis: '', dispositionRequirement: '' }) }
async function findProducts(target: number) { await run(async check => { if (target === 1) products.value = []; const values = result(await engineeringApi.list(productSearch.value, target)); check(); products.value.push(...values.filter(x => x.isCurrent && x.product.enabled)); productPage.value = target; moreProducts.value = values.length === 20 }) }
function chooseProduct(output: ManufacturingOutput, selected: string) { output.productRef = selected ? copy(products.value.find(x => key(x.reference) === selected)?.reference ?? output.productRef) : null }
async function findUnits(target: number) { await run(async check => { if (target === 1) units.value = []; const values = result(await uomApi.list(unitSearch.value, target)); check(); units.value.push(...values.filter(x => x.isCurrent && x.profile.enabled)); unitPage.value = target; moreUnits.value = values.length === 20 }) }
function chooseUnit(output: ManufacturingOutput, field: 'unitRef' | 'denominatorUnitRef', selected: string) { output[field] = selected ? copy(units.value.find(x => key(x.reference) === selected)?.reference ?? output[field]) : null }
async function save() { const s = scope.value, b = body.value; if (!s || !b || !canWrite.value || pending.value) return; const command: Omit<ManufacturingCommand, 'operationId'> = { manufacturingId: id.value, action: current.value ? 'REVISE' : 'CREATE', expectedVersion: current.value?.reference.version ?? null, expectedEtag: current.value?.etag ?? null, body: copy(b), reason: reason.value }; await run(async check => { const guard = () => { check(); if (!canWrite.value) throw new Error('当前无权保存。') }; await saveManufacturing(s, command.manufacturingId, guard, operationId => manufacturingApi.save({ ...command, operationId })); check(); const value = result(await manufacturingApi.read(command.manufacturingId)); check(); setCurrent(value); await loadOriginalSources(value.body, check); rows.value = []; const values = result(await manufacturingApi.list()); check(); rows.value = values; page.value = 1; notice.value = '制造关系版本已保存，专业评审和冻结仍待完成。' }) }
async function recover(close: boolean) { const s = scope.value; if (!s) return; await run(async check => { const value = await resolveManufacturing(s, close, check); check(); if (value.state === 'COMMITTED') clearEditor(); notice.value = value.state === 'COMMITTED' ? '原操作已提交，请重新打开制造关系。' : value.state === 'CLOSED' ? '原操作已结束，可以继续编辑。' : '结果仍未知，请继续查询或结束未提交操作。' }) }
async function readHistory() { const value = current.value; if (!value) return; await run(async check => { history.value = null; const saved = result(await manufacturingApi.read(value.reference.id, historyVersion.value)); check(); history.value = saved }) }
async function readDiff() { const value = current.value; if (!value) return; await run(async check => { diff.value = null; const saved = result(await manufacturingApi.diff(value.reference.id, beforeVersion.value, afterVersion.value)); check(); diff.value = saved }) }
function clear() { generation++; busy.value = false; clearPrivate(); scope.value = null; pending.value = null; error.value = notice.value = '' }
function changed() { clear(); if (authenticationCanRead()) void reload() }
function storage(e: StorageEvent) { if (e.key?.startsWith('cp6_engineering_manufacturing_operation_v1:')) { try { syncPending() } catch { error.value = '原操作记录异常，请保留记录。' } } }
watch(canRead, allowed => { if (!allowed) clear() })
watch(parentChoice, () => { choices.value = []; routes.value = []; ebomChoice.value = mbomChoice.value = routeChoice.value = ''; moreSources.value = false })
onMounted(() => { window.addEventListener(AUTH_EVENT, changed); window.addEventListener('storage', storage); void reload() })
onBeforeUnmount(() => { live = false; generation++; clearPrivate(); window.removeEventListener(AUTH_EVENT, changed); window.removeEventListener('storage', storage) })
</script>
<style scoped>
.manufacturing-page{display:grid;gap:18px;padding:24px;color:var(--el-text-color-primary)}header,.inline,nav{display:flex;gap:12px;align-items:center;flex-wrap:wrap}header{justify-content:space-between}section,article{padding:18px;border:1px solid var(--el-border-color);border-radius:8px;background:var(--el-bg-color)}article{margin:18px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px}label{display:grid;gap:6px;margin:8px 0}input,select,textarea,button{font:inherit;padding:8px;border:1px solid var(--el-border-color);border-radius:4px;color:inherit;background:var(--el-bg-color);max-width:100%;box-sizing:border-box}select[multiple]{min-height:100px}button{margin:4px;cursor:pointer}button:disabled{opacity:.5;cursor:default}fieldset{border:0;padding:0}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:400px;overflow:auto}[role=alert]{color:var(--el-color-danger)}:focus-visible{outline:2px solid var(--el-color-primary);outline-offset:2px}@media(max-width:600px){.manufacturing-page{padding:12px}section,article{padding:12px}}
</style>
